<?php
namespace Tests\Feature;
final class MarketResearchDatabaseOAuthTest extends ContentPlanDatabaseOAuthTest {
 public function test_each_market_research_entity_runs_create_update_archive_with_database_oauth():void{
  [$bearer]=$this->databaseToken($this->authorizedUser,['marketing:read','marketing:write']);
  $cases=['four_p'=>['nama_analisis'=>'Product','type'=>'product','platform'=>'Instagram'],'swot'=>['strenght'=>'Strong','platform'=>'Instagram'],'segmentation'=>['usia'=>'18-35','platform'=>'Instagram'],'target_audience'=>['indikator'=>'Young professionals','platform'=>'Instagram'],'positioning'=>['indikator'=>'Trusted','deskripsi'=>'Practical partner','platform'=>'Instagram']];
  foreach($cases as $entity=>$payload){$token=$this->confirmResearch($bearer,$entity,'create',0,$payload);$created=$this->withToken($bearer)->postJson("/api/oauth-marketing-crud/market-research/{$entity}",$payload+['client_id'=>$this->allowedClient,'confirmation_token'=>$token])->assertCreated();$id=(int)$created->json('data.id');$update=$payload;$first=array_key_first($update);$update[$first].=' updated';$ut=$this->confirmResearch($bearer,$entity,'update',$id,$update);$this->withToken($bearer)->patchJson("/api/oauth-marketing-crud/market-research/{$entity}/{$id}",$update+['client_id'=>$this->allowedClient,'confirmation_token'=>$ut])->assertOk();$archive=['reason'=>'Research superseded'];$at=$this->confirmResearch($bearer,$entity,'archive',$id,$archive);$this->withToken($bearer)->postJson("/api/oauth-marketing-crud/market-research/{$entity}/{$id}/archive",$archive+['confirmation_token'=>$at])->assertOk();}
  $this->withToken($bearer)->getJson("/api/oauth-marketing-mcp/clients/{$this->allowedClient}/market-research")->assertOk()->assertJsonPath('pagination.total',0);
  $this->activityLog->flush();$records=array_filter($this->firestore->records,fn($r)=>str_starts_with($r['data']['module']??'','market_research_'));$this->assertCount(15,$records);$serialized=json_encode($records,JSON_THROW_ON_ERROR);$this->assertDoesNotMatchRegularExpression('/confirmation_token|password|credential|private[_-]?key/i',$serialized);
 }
 public function test_market_research_rejects_permission_client_tampering_and_token_replay():void{
  $viewer=$this->makeUser('Research Viewer','research-viewer@example.test','Content Creator','Digital Marketing',true);[$viewerToken]=$this->databaseToken($viewer,['marketing:write']);$payload=['nama_analisis'=>'Product','type'=>'product','platform'=>'Instagram'];$this->withToken($viewerToken)->postJson('/api/oauth-marketing-crud/market-research/four_p/confirmation',['action'=>'create','client_id'=>$this->allowedClient,'payload'=>$payload])->assertForbidden();$this->app['auth']->forgetGuards();[$bearer]=$this->databaseToken($this->authorizedUser,['marketing:write']);$token=$this->confirmResearch($bearer,'four_p','create',0,$payload);$this->withToken($bearer)->postJson('/api/oauth-marketing-crud/market-research/four_p',$payload+['client_id'=>$this->allowedClient,'confirmation_token'=>$token])->assertCreated();$this->withToken($bearer)->postJson('/api/oauth-marketing-crud/market-research/four_p',$payload+['client_id'=>$this->allowedClient,'confirmation_token'=>$token])->assertStatus(422);$wrong=$this->confirmResearch($bearer,'four_p','create',0,$payload);$this->withToken($bearer)->postJson('/api/oauth-marketing-crud/market-research/four_p',$payload+['client_id'=>$this->otherClient,'confirmation_token'=>$wrong])->assertStatus(422);
 }
 private function confirmResearch(string $bearer,string $entity,string $action,int $id,array $payload):string{return $this->withToken($bearer)->postJson("/api/oauth-marketing-crud/market-research/{$entity}/confirmation",['action'=>$action,'client_id'=>$this->allowedClient,'record_id'=>$id,'payload'=>$payload])->assertOk()->json('data.confirmation_token');}
}
